use ingetrazo_gui::IngeTrazoApp;use ingetrazo_core::scene::SelectionItem;
fn main(){let dir=std::path::PathBuf::from(std::env::args().nth(1).unwrap());let mut source=IngeTrazoApp::new();source.scene=ingetrazo_formats::igz::load_igz(&dir.join("overlap-source.igz")).unwrap();source.scene.select(SelectionItem::Face(0));source.copy_selection();let mut destination=IngeTrazoApp::new();destination.scene=ingetrazo_formats::igz::load_igz(&dir.join("overlap-destination.igz")).unwrap();destination.clipboard=source.clipboard.clone();let before=destination.scene.clone();destination.paste_in_place();assert_eq!(destination.undo_stack.len(),1);assert!(!destination.scene.selection.is_empty());ingetrazo_formats::igz::save_igz(&destination.scene,&dir.join("overlap-result.igz")).unwrap();destination.undo();assert_eq!(destination.scene,before);destination.redo();assert_eq!(destination.undo_stack.len(),1);}
